  @protected
  void sse_encode_transport_dto(TransportDto self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case TransportDto_PlayFile(path: final path):
        sse_encode_i_32(0, serializer);
        sse_encode_String(path, serializer);
      case TransportDto_Pause():
        sse_encode_i_32(1, serializer);
      case TransportDto_Resume():
        sse_encode_i_32(2, serializer);
      case TransportDto_Seek(ms: final ms):
        sse_encode_i_32(3, serializer);
        sse_encode_u_64(ms, serializer);
      case TransportDto_Stop():
        sse_encode_i_32(4, serializer);
    }
  }

